// test:contract — contract tests generated by Schemathesis against the running server
// (FR-051, US5). Starts the server on a free port, waits for it to respond, runs
// `uvx schemathesis` on the bundle and stops the server propagating the exit code.
//
// Both credentials travel in every request (015 F-054): the ingest key for the SDK operations
// and the platform key for the server-to-server ones, so no built operation is exercised only
// through its 401. The contract merchant declares no platform secret: unsigned requests are
// what the contract describes, and the signature is tested by tests/integration.
//
// Schemathesis reports a "schema validation mismatch" warning: the operations with
// `x-invariants` answer 422 to bodies the schema admits (ADR-007), and the report counts each of
// those answers, expected by the contract, as a mismatch between schema and behaviour. The
// warning is informative; the checks are what fail the run.
//
// Manual negative test: OPE_SERVER_ENTRY=tests/contract/fixtures/health-203.ts npm run test:contract
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { bundlePath, repoRoot } from "./lib.mjs";
import { startBuiltServer } from "./server-lib.mjs";

// Pinned version: the same locally and in CI.
const SCHEMATHESIS = "schemathesis@4.27.2";

/** Test operator for Schemathesis (feature 017): the token travels as a bearer; only its fingerprint is configured. */
const CONTRACT_ADMIN_TOKEN = "ope_contract_admin_token";
const CONTRACT_OPERATOR = {
  operatorId: "contract-test-operator",
  tokenFingerprints: [createHash("sha256").update(CONTRACT_ADMIN_TOKEN, "utf8").digest("hex")],
  scope: "*",
};

/** Test merchant for Schemathesis: both credentials travel in every request; no signature secret. */
const CONTRACT_MERCHANT = {
  merchantId: "contract-test-merchant",
  ingestKeys: ["ope_contract_test_key"],
  platformKeys: ["ope_contract_platform_key"],
  origins: ["http://127.0.0.1"],
};

/**
 * The newest modification under a directory, in ms.
 * @param {string} dir
 * @returns {number}
 */
function newestUnder(dir) {
  let newest = 0;
  for (const entry of readdirSync(dir, { recursive: true, withFileTypes: true })) {
    if (!entry.isFile()) continue;
    const at = statSync(path.join(entry.parentPath, entry.name)).mtimeMs;
    if (at > newest) newest = at;
  }
  return newest;
}

/** @returns {string | null} the reason the run cannot start, or null */
function preflight() {
  const uvx = spawnSync("uvx", ["--version"], { encoding: "utf8" });
  if (uvx.status !== 0) return "`uvx` not found. Install uv: https://docs.astral.sh/uv/";
  if (!existsSync(bundlePath)) return `${bundlePath} does not exist. Run npm run contract:bundle.`;
  // A stale build is the worst failure this script can produce: it starts the server of the previous
  // commit and reports today's code as broken (feature 027). Refusing is the whole fix.
  const built = path.join(repoRoot, "dist", "main.js");
  if (process.env["OPE_SERVER_ENTRY"] === undefined && existsSync(built)) {
    const sources = newestUnder(path.join(repoRoot, "src"));
    if (sources > statSync(built).mtimeMs) {
      return "dist/ is older than src/: this would test the previous build. Run npm run build.";
    }
  }
  return null;
}

/**
 * Runs Schemathesis against `base` and returns its exit code.
 * @param {string} base
 * @returns {number}
 */
function runSchemathesis(base) {
  const st = spawnSync(
    "uvx",
    [
      SCHEMATHESIS,
      "run",
      bundlePath,
      "--url",
      base,
      "--checks",
      "all",
      "--phases",
      "examples,coverage,fuzzing",
      "--max-examples",
      "50",
      // Both credentials: each authenticated operation reads its own (401 without it, and
      // Schemathesis also tests that path by removing the header).
      "-H",
      `X-OPE-Ingest-Key: ${CONTRACT_MERCHANT.ingestKeys[0] ?? ""}`,
      "-H",
      `X-OPE-Platform-Key: ${CONTRACT_MERCHANT.platformKeys[0] ?? ""}`,
      "-H",
      `Authorization: Bearer ${CONTRACT_ADMIN_TOKEN}`,
      "--report",
      "junit",
      "--report-dir",
      path.join(repoRoot, ".schemathesis"),
    ],
    {
      stdio: "inherit",
      cwd: repoRoot,
      // UTF-8 output also on Windows consoles (cp1252).
      env: { ...process.env, PYTHONIOENCODING: "utf-8", PYTHONUTF8: "1" },
    },
  );
  return st.status ?? 1;
}

/** @returns {Promise<number>} */
async function main() {
  const blocker = preflight();
  if (blocker !== null) {
    console.error(`test:contract — ${blocker}`);
    return 1;
  }
  const server = await startBuiltServer({
    OPE_MERCHANTS: process.env["OPE_MERCHANTS"] ?? JSON.stringify([CONTRACT_MERCHANT]),
    OPE_ADMIN_OPERATORS: process.env["OPE_ADMIN_OPERATORS"] ?? JSON.stringify([CONTRACT_OPERATOR]),
  });
  try {
    console.log(`test:contract — server at ${server.base}; running Schemathesis…`);
    return runSchemathesis(server.base);
  } finally {
    await server.stop();
  }
}

main()
  .then((code) => process.exit(code))
  .catch((/** @type {unknown} */ err) => {
    console.error(`test:contract — ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  });
